(function(){
  // If admin → show all records; else filter by trainer
  const trainer = frappe.session.user !== "Administrator" ? frappe.session.user : null;

  const root = root_element;

  let statusFilter = null; 

  // State
  let currentPage = 1;
  const pageSize = 20;
  let totalRecords = 0;
  let searchText = "";
  let dateFrom = null;
  let dateTo = null;
  let currentOffset = 0;

  // Page cache storage
  const pageCache = {};   // { page: logs[] }

  function clearCache() {
    Object.keys(pageCache).forEach(k => delete pageCache[k]);
  }

  function getFirstDayOfMonth() {
    const date = new Date();
    return new Date(date.getFullYear(), date.getMonth(), 1);
  }

  function formatDate(date) {
    const d = new Date(date);
    const month = String(d.getMonth() + 1).padStart(2, "0");
    const day = String(d.getDate()).padStart(2, "0");
    return `${d.getFullYear()}-${month}-${day}`;
  }

  function initializeDates() {
    const today = new Date();
    const firstDay = getFirstDayOfMonth();
    dateFrom = formatDate(firstDay);
    dateTo = formatDate(today);
    root.querySelector(".aad-date-from").value = dateFrom;
    root.querySelector(".aad-date-to").value = dateTo;
  }

