function getFilters(search = "") {
  const filters = getBaseFilters(search);

  if (statusFilter === "stay") {
    filters["wants_to_stay"] = 1;
  } 
  else if (statusFilter === "exit") {
    filters["want_to_exit"] = 1;
  } 
  else if (statusFilter === "exited") {
    filters["exited"] = 1;
  }

  return filters;
}



  function getStatusInfo(log) {
    if (log.wants_to_stay) {
      return { label: "Wants to Stay", indicator: "green" };
    } else if (log.want_to_exit) {
      return { label: "Want to Exit", indicator: "red" };
    } else if (log.exited) {
      return { label: "Exited", indicator: "orange" };
    } else {
      return { label: "Pending", indicator: "gray" };
    }
  }

  async function fetchTotalCount(filters = {}) {
    try {
      const result = await frappe.call({
        method: "frappe.client.get_count",
        args: { doctype: "Agent Activation Call Log", filters: filters }
      });
      return result.message || 0;
    } catch (error) {
      console.error("Error fetching count:", error);
      return 0;
    }
  }

