script:
// -------------------------
// Change Password Dialog
// -------------------------
root_element.querySelector('#change-password-btn').addEventListener('click', function () {

    if (frappe.session.user === "Administrator") {
        frappe.msgprint(__('Administrator cannot update password from here.'));
        return;
    }

    const d = new frappe.ui.Dialog({
        title: 'Change Your Password',
        fields: [
            { label: 'Old Password', fieldname: 'old_password', fieldtype: 'Password', reqd: 1 },
            { label: 'New Password', fieldname: 'new_password', fieldtype: 'Password', reqd: 1 },
            { label: 'Confirm Password', fieldname: 'confirm_password', fieldtype: 'Password', reqd: 1 }
        ],
        primary_action_label: 'Change Password',
        primary_action(values) {
            if (values.new_password !== values.confirm_password) {
                frappe.msgprint(__('New and Confirm Passwords do not match'));
                return;
            }

            frappe.call({
                method: 'sahayog.api.update_emp_details.custom_change_password',
                args: {
                    old_password: values.old_password,
                    new_password: values.new_password
                },
                callback: function (r) {
                    if (r.message?.status === "success") {
                        frappe.msgprint({
                            title: __('Success'),
                            message: r.message.message || __('Password updated successfully.'),
                            indicator: 'green'
                        });
                        d.hide();
                    } else {
                        frappe.msgprint({
                            title: __('Error'),
                            message: r.message?.message || __('Something went wrong'),
                            indicator: 'red'
                        });
                    }
                }
            });
        }
    });

    d.show();
});

// -------------------------
// Update Employee Details Dialog
// -------------------------
root_element.querySelector('#update-details-btn').addEventListener('click', async function () {

    if (frappe.session.user === "Administrator") {
        frappe.msgprint(__('Administrator cannot update details.'));
        return;
    }

    let employee = await frappe.db.get_value("Employee", { user_id: frappe.session.user }, [
        "name", "first_name", "middle_name", "last_name",
        "date_of_birth", "date_of_joining",
        "designation", "department", "branch",
        "custom_zone", "custom_region",
        "cell_number", "company_email", "sol_id"
    ]);

    let emp = employee?.message || {};

    const empDialog = new frappe.ui.Dialog({
        title: 'Employee Details',
        fields: [
            { fieldtype: 'Section Break', label: 'Personal Information' },
            { label: 'First Name', fieldname: 'first_name', fieldtype: 'Data', default: emp.first_name || "", read_only: 1 },
            { fieldtype: 'Column Break' },
            { label: 'Middle Name', fieldname: 'middle_name', fieldtype: 'Data', default: emp.middle_name || "", read_only: 1 },
            { fieldtype: 'Column Break' },
            { label: 'Last Name', fieldname: 'last_name', fieldtype: 'Data', default: emp.last_name || "", read_only: 1 },

            { fieldtype: 'Section Break' },
            { label: 'Date of Birth', fieldname: 'date_of_birth', fieldtype: 'Date', default: emp.date_of_birth || "", read_only: 1 },
            { fieldtype: 'Column Break' },
            { label: 'Date of Joining', fieldname: 'date_of_joining', fieldtype: 'Date', default: emp.date_of_joining || "", read_only: 1 },

            { fieldtype: 'Section Break', label: 'Work Information' },
            { label: 'Designation', fieldname: 'designation', fieldtype: 'Link', options: 'Designation', default: emp.designation || "", read_only: 1 },
            { fieldtype: 'Column Break' },
            { label: 'Department', fieldname: 'department', fieldtype: 'Link', options: 'Department', default: emp.department || "", read_only: 1 },

            { fieldtype: 'Section Break' },
            { label: 'Branch', fieldname: 'branch', fieldtype: 'Link', options: 'Branch', default: emp.branch || "", read_only: 1 },
            { fieldtype: 'Column Break' },
            { label: 'SOL ID', fieldname: 'sol_id', fieldtype: 'Data', default: emp.sol_id || "", read_only: 1 },
            { fieldtype: 'Column Break' },
            { label: 'Zone', fieldname: 'custom_zone', fieldtype: 'Link', options: 'Zone', default: emp.custom_zone || "", read_only: 1 },
            { fieldtype: 'Column Break' },
            { label: 'Region', fieldname: 'custom_region', fieldtype: 'Link', options: 'Region', default: emp.custom_region || "", read_only: 1 },

            { fieldtype: 'Section Break', label: 'Contact Information' },
            { label: 'Cell Number', fieldname: 'cell_number', fieldtype: 'Data', default: emp.cell_number || "", read_only: 1 },
            { fieldtype: 'Column Break' },
            { label: 'Company Email', fieldname: 'company_email', fieldtype: 'Data', default: emp.company_email || "", read_only: 1 }
        ],
        primary_action_label: 'Edit',
        primary_action(values) {
            if (empDialog.get_primary_btn().text() === 'Edit') {
                Object.keys(empDialog.fields_dict).forEach(f => {
                    if (f !== "sol_id") {
                        empDialog.fields_dict[f].df.read_only = 0;
                    }
                });
                empDialog.refresh();
                empDialog.get_primary_btn().text('Save');
            } else {
                if (values.company_email && !values.company_email.endsWith('@sahayogmultistate.com')) {
                    frappe.msgprint(__('Email must end with @sahayogmultistate.com'));
                    return;
                }

                frappe.call({
                    method: 'sahayog.api.update_emp_details.update_employee_details',
                    args: {
                        employee: emp.name,
                        data: JSON.parse(JSON.stringify(values))
                    },
                    callback(r) {
                        if (r.message?.status === "success") {
                            frappe.msgprint({
                                title: __('Success'),
                                message: __('Employee details updated successfully'),
                                indicator: 'green'
                            });

                            empDialog.hide();

                            const iframe = root_element.querySelector('#home_frame');
                            if (iframe && !window._iframe_refreshed) {
                                window._iframe_refreshed = true;
                                iframe.src = iframe.src;
                            }
                            setCompanyEmailButtonText();
                        } else {
                            frappe.msgprint({
                                title: __('Error'),
                                message: r.message?.message || __('Something went wrong.'),
                                indicator: 'red'
                            });
                        }
                    }
                });
            }
        }
    });

    empDialog.show();
});

