}

// -------------------------
// VCARD BUTTON
// -------------------------
root_element.querySelector("#vcard-btn")
  ?.addEventListener("click", open_vcard_modal);

// -------------------------
// OPEN VCARD
// -------------------------
function open_vcard_modal() {

  frappe.db.get_value(
    "Employee",
    { user_id: frappe.session.user },
    ["first_name", "designation", "branch", "cell_number", "company_email"]
  ).then(r => {

    if (!r.message) {
      frappe.msgprint("Employee record not found");
      return;
    }

    frappe.call({
      method: "sahayog.api.employee_vcard.get_employee_vcard_qr",
      callback(res) {
        render_vcard(r.message, res.message.qr_base64);
      }
    });
  });
}

// -------------------------
// RENDER VCARD (PURE DOM)
// -------------------------
function render_vcard(emp, qr) {

  document.getElementById("vcard-overlay")?.remove();

  const overlay = document.createElement("div");
  overlay.id = "vcard-overlay";
  overlay.style.cssText = `
    position:fixed;
    inset:0;
    background:rgba(0,0,0,.65);
    z-index:10000;
    display:flex;
    align-items:center;
    justify-content:center;
  `;

  overlay.innerHTML = `
  <div style="background:#fff;padding:30px;border-radius:12px; position:relative">
  <button id="vcard-close"
  style="
    position:absolute;
    top:10px;
    right:10px;
    width:28px;
    height:28px;
    border:none;
    border-radius:50%;
    background:#0f7f7a;
    color:#fff;
    font-size:16px;
    cursor:pointer">
  ✕
</button>


    <div id="vcard-poster"
      style="
        width:320px;
        height:500px;
        background:#fff;
        border-radius:16px;
        box-shadow:0 6px 18px rgba(0,0,0,.25);
        position:relative;
        overflow:hidden;
        font-family:Arial;
      ">

      <div style="text-align:center;padding:14px">
        <img src="/assets/sahayog/images/sahayog_logo_2025.png"
             style="height:44px">
      </div>

      <div style="
        width:78px;height:78px;
        border-radius:50%;
        border:4px solid #0f7f7a;
        background:#f2f2f2;
        margin:4px auto;
        display:flex;
        align-items:center;
        justify-content:center;
        font-size:30px">👤</div>

      <h3 style="margin:6px 0 2px;text-align:center">
        ${emp.first_name}
      </h3>

      <p style="margin:0;text-align:center;font-size:12px;color:#555">
        ${emp.designation}
      </p>

      <hr style="margin:10px 24px">

      <div style="font-size:12px;padding:0 24px">
        <p>📞 ${emp.cell_number}</p>
        <p>✉️ ${emp.company_email}</p>
        <p>🏢 ${emp.branch}</p>
      </div>

      <div style="text-align:center;margin-top:8px">
        <img src="data:image/png;base64,${qr}"
             style="width:140px;height:140px">
      </div>

      <div style="
        position:absolute;
        bottom:0;
        width:100%;
        height:16px;
        background:#0f7f7a"></div>
    </div>

    <button id="download-vcard"
      style="
        width:100%;
        margin-top:12px;
        padding:10px;
        background:#000;
        color:#fff;
        border-radius:6px;
        border:none;
        cursor:pointer">
      Download vCard
    </button>

  </div>`;

  document.body.appendChild(overlay);
  document.getElementById("vcard-close").onclick = () =>
  document.getElementById("vcard-overlay")?.remove();

overlay.onclick = e => {
  if (e.target === overlay) overlay.remove();
};


  bind_download(emp.first_name);
}

// -------------------------
// 🔥 DOWNLOAD — GUARANTEED
// -------------------------
function bind_download(name) {

  document.getElementById("download-vcard").onclick = async () => {

    const original = document.getElementById("vcard-poster");
    const clone = original.cloneNode(true);

    clone.style.position = "absolute";
    clone.style.top = "-2000px";
    clone.style.left = "0";
    clone.style.boxShadow = "none";

    document.body.appendChild(clone);

    const canvas = await html2canvas(clone, {
      scale: 3,
      backgroundColor: "#ffffff",
      useCORS: true
    });

    const a = document.createElement("a");
    a.href = canvas.toDataURL("image/png");
    a.download = `${name}_vCard.png`;

    a.click();
    clone.remove();
  };
}

// ---------------- Initialize Dashboard ----------------
function init(root_element) {
  root_element.caseOffset = 0;     // starting index
  root_element.caseLimit = 5;      // 5 cases per page
  root_element.allCases = [];      // store fetched cases

  attachEvents(root_element);
  fetchDashboardData(root_element);
}

// ---------------- Fetch Data ----------------
function fetchDashboardData(root_element) {
  frappe.call({
    method: 'frappe.client.get_list',
    args: {
      doctype: 'Disciplinary Case',
      fields: [
        'name', 'case_id', 'employee_id', 'employee_name', 'designation',
        'branch_name', 'zone', 'case_type', 'category',
        'issue_occurrence_date', 'issue_report_to_hr', 'case_status'
      ],
      limit_page_length: 1000,
      order_by: 'modified desc'
    },
    callback: res => {
      const cases = res.message || [];
      const total = cases.length;
      const underProcess = cases.filter(c => c.case_status === 'Under Process').length;
      const closed = cases.filter(c => c.case_status === 'Closed').length;

      updateWidgets(root_element, { total, underProcess, closed });

      root_element.allCases = cases;
      root_element.caseOffset = 0;
      renderCases(root_element, true); // render first 5
    }
  });
}

// ---------------- Update Widgets ----------------
function updateWidgets(root_element, { total, underProcess, closed }) {
  const totalCard = root_element.querySelector('#widget-total');
  const underProcessCard = root_element.querySelector('#widget-under-process');
  const closedCard = root_element.querySelector('#widget-closed');

  if (totalCard) {
    totalCard.querySelector('.value').textContent = total;
    totalCard.onclick = () => window.location.href = '/app/disciplinary-case';
  }

  if (underProcessCard) {
    underProcessCard.querySelector('.value').textContent = underProcess;
    underProcessCard.onclick = () => window.location.href = '/app/disciplinary-case?case_status=Under%20Process';
  }

  if (closedCard) {
    closedCard.querySelector('.value').textContent = closed;
    closedCard.onclick = () => window.location.href = '/app/disciplinary-case?case_status=Closed';
  }
}

// ---------------- Render Cases ----------------
function renderCases(root_element, reset = false) {
  const container = root_element.querySelector('#cases-list');
  const loadMoreBtn = root_element.querySelector('#load-more-btn');
  if (!container) return;

  if (reset) container.innerHTML = '';

  const { allCases, caseOffset, caseLimit } = root_element;
  const nextCases = allCases.slice(caseOffset, caseOffset + caseLimit);

  if (nextCases.length === 0 && reset) {
    container.innerHTML = '<p>No cases found.</p>';
    loadMoreBtn.style.display = 'none';
    return;
  }

  nextCases.forEach(dc => {
    const div = document.createElement('div');
    div.className = 'case-item';

    div.innerHTML = `
      <div class="case-header">
        <div class="case-title" data-case-name="${dc.name}" title="Open Case">
          ${dc.case_id || dc.name}
        </div>
        <button class="btn-view" data-case-name="${dc.name}">View</button>
      </div>

      <table class="case-details-table">
        <tr><td><strong>Case ID:</strong></td><td>${dc.case_id || '-'}</td></tr>
        <tr><td><strong>Employee ID:</strong></td><td>${dc.employee_id || '-'}</td></tr>
        <tr><td><strong>Employee Name:</strong></td><td>${dc.employee_name || '-'}</td></tr>
        <tr><td><strong>Designation:</strong></td><td>${dc.designation || '-'}</td></tr>
        <tr><td><strong>Branch Name:</strong></td><td>${dc.branch_name || '-'}</td></tr>
        <tr><td><strong>Zone Name:</strong></td><td>${dc.zone || '-'}</td></tr>
        <tr><td><strong>Case Type:</strong></td><td>${dc.case_type || '-'}</td></tr>
        <tr><td><strong>Category:</strong></td><td>${dc.category || '-'}</td></tr>
        <tr><td><strong>Issue Occurrence Date:</strong></td><td>${formatDate(dc.issue_occurrence_date)}</td></tr>
        <tr><td><strong>Issue Date Reported To HR:</strong></td><td>${formatDate(dc.issue_report_to_hr)}</td></tr>
        <tr><td><strong>Case Status:</strong></td><td>${dc.case_status || '-'}</td></tr>
      </table>
    `;
    container.appendChild(div);
  });

  // Click events
  container.querySelectorAll('[data-case-name]').forEach(el => {
    el.onclick = () => {
      const caseName = el.getAttribute('data-case-name');
      if (caseName) window.location.href = `/app/disciplinary-case/${caseName}`;
    };
  });

  // Update offset and toggle Load More button
  root_element.caseOffset += nextCases.length;
  if (root_element.caseOffset < root_element.allCases.length) {
    loadMoreBtn.style.display = 'block';
  } else {
    loadMoreBtn.style.display = 'none';
  }
}

// ---------------- Helper Functions ----------------
function attachEvents(root_element) {
  const newCaseBtn = root_element.querySelector('.dm-btn-new');
  if (newCaseBtn)
    newCaseBtn.onclick = () => window.location.href = '/app/disciplinary-case/new';

  const loadMoreBtn = root_element.querySelector('#load-more-btn');
  if (loadMoreBtn)
    loadMoreBtn.onclick = () => renderCases(root_element, false);
}

function formatDate(dateStr) {
  if (!dateStr) return '-';
  const d = new Date(dateStr);
  return d.toLocaleDateString('en-IN', { day: '2-digit', month: 'short', year: 'numeric' });
}

// ---------------- Run ----------------
init(root_element);

