(function () {
    const chartContainer = root_element.querySelector("#product-type-chart-container");
    if (!chartContainer) return;

    const chartElement = root_element.querySelector("#product-type-chart");
    if (!chartElement) return;

    // Destroy old chart instance if it exists
    if (chartElement.chartInstance) chartElement.chartInstance.destroy();

    function loadChartJS(callback) {
        if (typeof Chart !== "undefined") {
            callback();
            return;
        }
        const script = document.createElement("script");
        script.src = "https://cdn.jsdelivr.net/npm/chart.js";
        script.onload = callback;
        document.head.appendChild(script);
    }

    loadChartJS(() => {

        // STEP 1: Fetch all products
        frappe.call({
            method: "frappe.client.get_list",
            args: {
                doctype: "Product",
                fields: ["name", "product_type", "product_name"],
                limit_page_length: 1000
            },
            callback: function (productResponse) {
                const products = productResponse.message || [];
                if (products.length === 0) {
                    chartContainer.innerHTML = "<p style='text-align:center;'>No product records found</p>";
                    return;
                }

                // STEP 2: Fetch lead counts from backend
                frappe.call({
                    method: "sahayog.scrm.api.sahayog_crm_dashboard.get_product_lead_counts",
                    callback: function (leadResponse) {
                        const leadCountMap = leadResponse.message || {};

                        // STEP 3: Prepare chart datasets
                        const allProductTypes = ["SBA", "CAA", "ODA", "TDA", "LAA", "OAB", "OAP", "INSURANCE", "AGENT"];
                        const pastelColors = [
                            "#76c7c0", "#a4d4ae", "#f7b267", "#f28b82", "#d7aefb",
                            "#aec6cf", "#ffb347", "#b39eb5", "#77dd77", "#ff6961"
                        ];

                        const productColorMap = {};
                        let colorIndex = 0;
                        const uniqueNames = Array.from(new Set(products.map(p => p.product_name)));
                        uniqueNames.forEach(name => {
                            productColorMap[name] = pastelColors[colorIndex % pastelColors.length];
                            colorIndex++;
                        });

                        // Create datasets and calculate total leads per product type
                        const datasets = [];
                        const typeLeadTotals = {}; // keep sum of leads per type

                        allProductTypes.forEach((type, typeIndex) => {
                            const productsOfType = products.filter(p => p.product_type === type);
                            let typeTotal = 0;

                            productsOfType.forEach(prod => {
                                const leadCount = leadCountMap[prod.name] || 0;
                                typeTotal += leadCount;

                                if (leadCount > 0) { // ✅ only include products with leads
                                    const dataArray = Array(allProductTypes.length).fill(0);
                                    dataArray[typeIndex] = leadCount;

                                    datasets.push({
                                        label: prod.product_name,
                                        product_code: prod.name,
                                        product_type: prod.product_type,
                                        lead_count: leadCount,
                                        data: dataArray,
                                        backgroundColor: productColorMap[prod.product_name]
                                    });
                                }
                            });

                            typeLeadTotals[type] = typeTotal;
                        });

                        // ✅ Filter out product types that have zero total leads
                        const productTypes = allProductTypes.filter(type => typeLeadTotals[type] > 0);

                        // If no types left, show message
                        if (productTypes.length === 0) {
                            chartContainer.innerHTML = "<p style='text-align:center;'>No lead data available</p>";
                            return;
                        }

                        // Filter datasets accordingly (only those belonging to valid types)
                        const filteredDatasets = datasets.map(ds => {
                            const dataArray = [];
                            productTypes.forEach(type => {
                                dataArray.push(
                                    ds.product_type === type ? ds.lead_count : 0
                                );
                            });
                            return { ...ds, data: dataArray };
                        });

                        // STEP 4: Adjust chart height dynamically
                        const totalProducts = filteredDatasets.length;
                        const height = totalProducts > 50 ? "800px" : totalProducts > 20 ? "600px" : "400px";
                        chartContainer.style.height = height;

                        // STEP 5: Calculate suggested max for better spacing
                        const maxLeadCount = Math.max(...filteredDatasets.map(d => d.lead_count));
                        const suggestedMax = Math.ceil(maxLeadCount * 1.2);

                        // STEP 6: Render chart
                        const ctx = chartElement.getContext("2d");
                        chartElement.chartInstance = new Chart(ctx, {
                            type: "bar",
                            data: { labels: productTypes, datasets: filteredDatasets },
                            options: {
                                responsive: true,
                                maintainAspectRatio: false,
                                plugins: {
                                    tooltip: {
                                        callbacks: {
                                            label: function (context) {
                                                const code = context.dataset.product_code || "";
                                                const name = context.dataset.label || "";
                                                const count = context.dataset.lead_count || 0;
                                                return `${code} : ${name} (Leads: ${count})`;
                                            }
                                        }
                                    },
                                    legend: { display: false },
                                    title: {
                                        display: true,
                                        text: "Products per Product Type (with Lead Counts)",
                                        font: { size: 18 }
                                    }
                                },
                                scales: {
                                    x: {
                                        stacked: true,
                                        title: { display: true, text: "Product Type" },
                                        grid: { display: false } // ❌ Hide vertical grid lines
                                    },
                                    y: {
                                        stacked: true,
                                        beginAtZero: true,
                                        suggestedMax: suggestedMax,
                                        title: { display: true, text: "Total Leads" },
                                        ticks: { autoSkip: true },
                                        grid: {
                                            display: true,
                                            color: "rgba(0, 0, 0, 0.05)", // 🌫️ Very light horizontal lines
                                            drawBorder: false,
                                            lineWidth: 1
                                        }
                                    }
                                }
                            }
                        });
                    }
                });
            }
        });
    });
})();

