  color: #6c757d;
}


/* Widget Grid */
.widgets-container,
.widgets-container-ad {
    display: grid;
    grid-template-columns: repeat(auto-fill, minmax(180px, 1fr));
    gap: 12px;
    margin: 16px 0;
}

.widget {
    padding: 16px;
    border-radius: 8px;
    background: white;
    box-shadow: 0 1px 2px rgba(0,0,0,0.1);
    transition: transform 0.2s, box-shadow 0.2s;
    text-decoration: none;
    border: 1px solid #e9ecef;
}

.widget:hover {
    transform: translateY(-2px);
    box-shadow: 0 4px 6px rgba(0,0,0,0.1);
}

.wid-title {
    font-size: 14px;
    font-weight: 500;
    color: #495057;
    margin-bottom: 12px;
}

.wid-content {
    display: flex;
    align-items: center;
    font-size: 13px;
    color: #212529;
}

.wid-content.red {
    color: #dc3545;
}

.wid-content.green {
    color: #28a745;
}

/* Status Dots */
.red-dot,
.green-dot,
.grey-dot {
    width: 8px;
    height: 8px;
    border-radius: 50%;
    margin-right: 8px;
}

.red-dot {
    background: #dc3545;
}

.green-dot {
    background: #28a745;
}

.grey-dot {
    background: #6c757d;
}

.value {
    font-weight: 600;
    margin-right: 4px;
}

/* Divider */
hr {
    border: 0;
    height: 1px;
    background: #e9ecef;
    margin: 16px 0;
}

/* Section Headers */
.widgets-container h2 {
    font-size: 18px;
    font-weight: 600;
    color: #343a40;
    margin: 8px 0;
    grid-column: 1 / -1;
}

/* Color Coding for Widgets */
#listLink, #allListBranch { border-left: 4px solid #6f42c1; }
#listDraft, #pendingListBranch { border-left: 4px solid #6610f2; }
#listClose, #ResponseListBranch { border-left: 4px solid #28a745; }
#listPendingAll, #closeListBranch { border-left: 4px solid #fd7e14; }

/* Pending Widgets (Red palette - 10 shades) */
#listPendingBM { border-left: 4px solid #ff0000; } /* Bright red */
#listPendingDH { border-left: 4px solid #ff5252; } /* Light red */
#listPendingCOM { border-left: 4px solid #ff1744; } /* Pinkish red */
#listPendingRM { border-left: 4px solid #d50000; } /* Dark red */
#listPendingROM { border-left: 4px solid #ff8a80; } /* Pale red */
#listPendingZM { border-left: 4px solid #c62828; } /* Brick red */
#listPendingZOM { border-left: 4px solid #ff3d00; } /* Orange-red */
#listPendingGM { border-left: 4px solid #b71c1c; } /* Deep red */
#listPendingHR { border-left: 4px solid #ff6e40; } /* Coral */
#listPendingCOO { border-left: 4px solid #dd2c00; } /* Rust */
#listPendingCEO { border-left: 4px solid #9e0000; } /* Maroon */

/* Response Widgets (Green palette - 10 shades) */
#listResponseBM { border-left: 4px solid #00c853; } /* Vibrant green */
#listResponseDH { border-left: 4px solid #64dd17; } /* Lime green */
#listResponseCOM { border-left: 4px solid #aeea00; } /* Chartreuse */
#listResponseRM { border-left: 4px solid #00e676; } /* Emerald */
#listResponseROM { border-left: 4px solid #76ff03; } /* Bright green */
#listResponseZM { border-left: 4px solid #1de9b6; } /* Teal green */
#listResponseZOM { border-left: 4px solid #00bfa5; } /* Sea green */
#listResponseGM { border-left: 4px solid #00b248; } /* Forest green */
#listResponseHR { border-left: 4px solid #b2ff59; } /* Light lime */
#listResponseCOO { border-left: 4px solid #4caf50; } /* Classic green */
#listResponseCEO { border-left: 4px solid #087f23; } /* Dark green */

/* No-Response Widgets (Blue palette - 11 shades) */
#listNoResponseBM { border-left: 4px solid #e3f2fd; }  /* Lightest Blue */
#listNoResponseDH { border-left: 4px solid #bbdefb; }  /* Sky Blue */
#listNoResponseCOM { border-left: 4px solid #90caf9; } /* Pale Blue */
#listNoResponseRM { border-left: 4px solid #64b5f6; }  /* Cool Blue */
#listNoResponseROM { border-left: 4px solid #42a5f5; } /* Moderate Blue */
#listNoResponseZM { border-left: 4px solid #2196f3; }  /* Standard Blue */
#listNoResponseZOM { border-left: 4px solid #1e88e5; } /* Slightly Darker */
#listNoResponseGM { border-left: 4px solid #1976d2; }  /* Dark Blue */
#listNoResponseHR { border-left: 4px solid #1565c0; }  /* Navy Blue */
#listNoResponseCOO { border-left: 4px solid #0d47a1; } /* Deep Blue */
#listNoResponseCEO { border-left: 4px solid #82b1ff; } /* Light Indigo */


/* Responsive Adjustments */
@media (max-width: 768px) {
    .widgets-container,
    .widgets-container-ad {
        grid-template-columns: 1fr 1fr;
    }

    .Asset-Container {
        flex-direction: column;
        align-items: flex-start;
    }

    .intro {
        margin-left: 0;
        margin-top: 12px;
    }
}

@media (max-width: 480px) {
    .widgets-container,
    .widgets-container-ad {
        grid-template-columns: 1fr;
    }

    .welcome-text {
        font-size: 18px;
    }

    .label {
        font-size: 14px;
    }
}

/* Tab Navigation */
.tabs-nav {
    display: flex;
    gap: 8px;
    margin: 20px 0 16px 0;
    border-bottom: 1px solid #e9ecef;
    padding-bottom: 8px;
}

.tab-button {
    padding: 8px 16px;
    border: none;
    background: none;
    cursor: pointer;
    font-size: 14px;
    font-weight: 500;
    color: #6c757d;
    border-radius: 4px;
    transition: all 0.2s ease;
    position: relative;
}

/* Hover for all tabs except active */
.tab-button:hover {
    color: #495057;
    background: #f8f9fa;
}

/* Active tab base styling */
.tab-button.active {
    background-color: #6f42c1;  /* Primary accent background */
    color: #ffffff;             /* White text for contrast */
    font-weight: 600;
}

/* Darker background on hover for active tab */
.tab-button.active:hover {
    background-color: #59359e;  /* Darker shade of #6f42c1 */
    color: #ffffff;
}

/* Remove underline effect if still present */
.tab-button.active::after {
    content: none;
}

/* Tab Content Areas (you'll need to add these classes to your content divs) */
.tab-content {
    display: none;
}

.tab-content.active {
    display: block;
}

script:
if (frappe.session.user === "Administrator") {
    const adminFullName = "Administrator"; // Manually set admin's full name
    const adminDesignation = "Admin"; // Manually set admin's designation
    console.log("Admin:", adminFullName, "-", adminDesignation);

    root_element.querySelector("#emp-name").textContent = adminFullName;


} else 
{

   const OpenTicketList = root_element.querySelector("#OpenTicketList");
    if (OpenTicketList) {
    const dynamicPart = `view/list?owner=${encodeURIComponent(frappe.session.user)}&status=Open`;
    OpenTicketList.href = '/app/sahayog-ticket/' + dynamicPart;
    }

    const ReadTicketList = root_element.querySelector("#ReadTicketList");
    if (ReadTicketList) {
    const dynamicPart = `view/list?owner=${encodeURIComponent(frappe.session.user)}&status=Read`;
    ReadTicketList.href = '/app/sahayog-ticket/' + dynamicPart;
     }

     const InProcessTicketList = root_element.querySelector("#InProcessTicketList");
    if (InProcessTicketList) {
    const dynamicPart = `view/list?owner=${encodeURIComponent(frappe.session.user)}&status=In-Process`;
    InProcessTicketList.href = '/app/sahayog-ticket/' + dynamicPart;
     }

     const OnHoldTicketList = root_element.querySelector("#OnHoldTicketList");
    if (OnHoldTicketList) {
    const dynamicPart = `view/list?owner=${encodeURIComponent(frappe.session.user)}&status=On-Hold`;
    OnHoldTicketList.href = '/app/sahayog-ticket/' + dynamicPart;
     }

     const ReOpenTicketList = root_element.querySelector("#ReOpenTicketList");
    if (ReOpenTicketList) {
    const dynamicPart = `view/list?owner=${encodeURIComponent(frappe.session.user)}&status=Re-Opened`;
    ReOpenTicketList.href = '/app/sahayog-ticket/' + dynamicPart;
     }

     const ResolvedTicketList = root_element.querySelector("#ResolvedTicketList");
    if (ResolvedTicketList) {
    const dynamicPart = `view/list?owner=${encodeURIComponent(frappe.session.user)}&status=Resolved`;
    ResolvedTicketList.href = '/app/sahayog-ticket/' + dynamicPart;
     }

     const ClosedTicketList = root_element.querySelector("#ClosedTicketList");
    if (ClosedTicketList) {
    const dynamicPart = `view/list?owner=${encodeURIComponent(frappe.session.user)}&status=Closed`;
    ClosedTicketList.href = '/app/sahayog-ticket/' + dynamicPart;
     }

     const CancelledTicketList = root_element.querySelector("#CancelledTicketList");
    if (CancelledTicketList) {
    const dynamicPart = `view/list?owner=${encodeURIComponent(frappe.session.user)}&status=Cancelled`;
    CancelledTicketList.href = '/app/sahayog-ticket/' + dynamicPart;
     }

    const empuser=frappe.session.user;
    const eid = empuser.match(/\d+/)[0];
    console.log("employee id:",eid);

   frappe.call({
    method: "sahayog_ticket.sahayog_ticket.doctype.sahayog_ticket.sahayog_ticket.get_counts",
    args: {
        employee_id: eid
    },
    callback: function(response) {
        var counts = response.message;
        console.log("Counts:", counts);

         if (root_element) {
            // Update count for ApprovalList
            var OpenTicketCount = counts.open || 0;
            console.log(OpenTicketCount);
            var openTicketElement = root_element.querySelector("#OpenTicketValue");
            if (openTicketElement) {
                openTicketElement.textContent = OpenTicketCount;
            }

            // Update count for DispatchList
            var ReadTicketCount = counts.read || 0;
            console.log(ReadTicketCount);
            var readTicketElement = root_element.querySelector("#ReadTicketValue");
            if (readTicketElement) {
                readTicketElement.textContent = ReadTicketCount;
            }

            // Update count for ReceivedList
            var InProgressTicketCount = counts.in_progress || 0;
            console.log(InProgressTicketCount);
            var inProgressTicketElement = root_element.querySelector("#InProcessTicketValue");
            if (inProgressTicketElement) {
                inProgressTicketElement.textContent = InProgressTicketCount;
            }

            // Update count for PurchaseList
            var OnHoldTicketCount = counts.on_hold || 0;
            console.log(OnHoldTicketCount);
            var onHoldTicketElement = root_element.querySelector("#OnHoldTicketValue");
            if (onHoldTicketElement) {
                onHoldTicketElement.textContent = OnHoldTicketCount;
            }

            // Update count for StoreList
            var ReOpenedTicketCount = counts.re_opened || 0;
            console.log(ReOpenedTicketCount);
            var reOpenedTicketElement = root_element.querySelector("#ReOpenTicketValue");
            if (reOpenedTicketElement) {
                reOpenedTicketElement.textContent = ReOpenedTicketCount;
            }

            // Update count for RejectedList
            var ResolvedTicketCount = counts.resolved || 0;
            console.log(ResolvedTicketCount);
            var resolvedTicketElement = root_element.querySelector("#ResolvedTicketValue");
            if (resolvedTicketElement) {
                resolvedTicketElement.textContent = ResolvedTicketCount;
            }

            // Update count for DeliveredList
            var ClosedTicketCount = counts.closed || 0;
            console.log(ClosedTicketCount);
            var closedTicketElement = root_element.querySelector("#ClosedTicketValue");
            if (closedTicketElement) {
                closedTicketElement.textContent = ClosedTicketCount;
            }

            // Update count for DraftList
            var CancelledTicketCount = counts.cancelled || 0;
            console.log(CancelledTicketCount);
            var cancelledTicketElement = root_element.querySelector("#CancelledTicketValue");
            if (cancelledTicketElement) {
                cancelledTicketElement.textContent = CancelledTicketCount;
            }
        }
    }
});

frappe.call({
    method: "frappe.client.get",
    args: {
        doctype: "Employee",
        filters: {'user_id': empuser}, // Pass filters to fetch details based on user_id
    },
    callback(r) {
        if (r.message) {
            const firstName = r.message.first_name;
            const lastName = r.message.last_name;
            const fullName = `${firstName} ${lastName}`;
            console.log("Fullname is:",fullName);
            root_element.querySelector("#emp-name").textContent ="Hello, " + fullName;

        } 
    }
});


}

style:
body, html {
    margin: 0;
    padding: 0;
    font-family: Arial, sans-serif;
}

.logo {
    width: 80px;
}

.Asset-Container {
    display: flex;
    flex-direction: row;
    align-items: center;
    padding: 10px;
}

.intro {
    margin-left: 15px;
}

.emp-name {
    margin-top: 18px;
    font-size: large;
}

.welcome-text {
    font-weight: bold;
    font-size: xx-large;
}

.asset-request-container {
    border: 1px solid #D9D9D9;
    padding: 10px;
    border-radius: 10px;
    margin-bottom: 15px;
}

.NewRequest {
    display: inline-flex;
    justify-content: space-between;
