    border: 2px solid black;
}

.widget:hover {
    transform: translateY(-3px);
    background-color: #eee;
    cursor: pointer;
    text-decoration: none;
}

.content-grid {
    display: flex;
    justify-content: space-between;
    align-items: center;
}

.wid-title {
    font-size: larger;
