}

/* Responsive styles for phones */
@media (max-width: 768px) {
    .widgets-container {
        flex-direction: column;
    }

    .widget {
        flex-basis: calc(50% - 10px); /* 2 widgets per row on small screens */
        max-width: calc(50% - 10px); /* 2 widgets per row on small screens */
    }

    .Asset-Container {
        flex-direction: column;
        align-items: flex-start;
    }

    .welcome-text {
